const CACHE='travelsplit-v1.2.0-albums';
const ASSETS=['assets/font-0.ttf','assets/font-1.ttf','assets/font-2.ttf','assets/font-3.ttf','assets/font-4.ttf','assets/font-5.ttf','assets/font-6.ttf','assets/font-7.ttf','assets/font-8.ttf','assets/font-9.ttf','./','index.html','styles.css','store.js','app.js','atlas.js','atlas.css','collaboration.js','collaboration.css','vendor/leaflet/leaflet.js','vendor/leaflet/leaflet.css','world.geojson','favicon.svg','manifest.webmanifest','assets/icon-192.png','assets/icon-512.png','assets/mountains.jpg','assets/forest.jpg','assets/italy.jpg','assets/japan.jpg'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(ASSETS)).then(()=>self.skipWaiting()))});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key.startsWith('travelsplit-')&&key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim()))});
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;event.respondWith(fetch(event.request).then(response=>{if(response.ok){const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy))}return response}).catch(()=>caches.match(event.request).then(response=>response||(event.request.mode==='navigate'?caches.match('index.html'):Response.error()))))});
